<?php
namespace App\Services;
use App\Models\Currency; use App\Support\Currency as CurrencyValue; use Illuminate\Support\Facades\DB; use RuntimeException;
class CurrencyConverter { public function convert(int $amount,string $from,string $to):int { $from=strtoupper($from);$to=strtoupper($to);if($from===$to)return $amount;$rate=DB::table('exchange_rates')->where('base_currency_code',$from)->where('quote_currency_code',$to)->where('is_active',true)->orderByDesc('effective_at')->value('rate');$inverse=false;if($rate===null){$rate=DB::table('exchange_rates')->where('base_currency_code',$to)->where('quote_currency_code',$from)->where('is_active',true)->orderByDesc('effective_at')->value('rate');$inverse=true;}if($rate===null)throw new RuntimeException("No exchange rate available for {$from} to {$to}.");$value=$this->decimalRatio((string)$rate);if($inverse){[$value[0],$value[1]]=[$value[1],$value[0]];} $src=(int)(Currency::where('code',$from)->value('minor_unit')??2);$dst=(int)(Currency::where('code',$to)->value('minor_unit')??2);$num=$amount*$value[0]*(10**$dst);$den=$value[1]*(10**$src);return (int)floor(($num*2+$den)/($den*2));} private function decimalRatio(string $v):array{if(!preg_match('/^(\d+)(?:\.(\d+))?$/',$v,$m))throw new RuntimeException('Invalid exchange rate.');$f=$m[2]??'';$scale=10**strlen($f);return [(int)$m[1]*$scale+(int)($f?:0),$scale];} }
